// mFRAMES — textes de l'interface : une seule table, quatre langues (fr rédigé en premier, en, es, it).
import Foundation

enum L {
    enum Lang: Int { case fr = 0, en, es, it }

    /// Langue du Mac si c'est l'une des quatre, sinon l'anglais ; `MFRAMES_LANG=fr|en|es|it` pour les essais.
    static var lang: Lang = {
        func lang(_ code: String) -> Lang? { switch code { case "fr": .fr; case "en": .en; case "es": .es; case "it": .it; default: nil } }
        if let forced = ProcessInfo.processInfo.environment["MFRAMES_LANG"] { return lang(forced) ?? .en }
        // Première langue préférée du Mac qui fait partie des quatre (« de, fr » donne le français), sinon l'anglais.
        return Locale.preferredLanguages.lazy.compactMap { lang(String($0.prefix(2))) }.first ?? .en
    }()

    static func t(_ key: String, _ args: CVarArg...) -> String {
        guard let row = table[key] else { return key }
        let s = row[lang.rawValue]
        return args.isEmpty ? s : String(format: s, arguments: args)
    }

    /// Clés dont une langue manque (utilisé par tests/check_l10n.sh).
    static func problems() -> [String] { table.filter { $0.value.count != 4 || $0.value.contains(where: { $0.isEmpty }) }.map(\.key).sorted() }

